11198  wasm_loader_prepare_bytecode(WASMModule *module, WASMFunction *func,
 11199                               uint32 cur_func_idx, char *error_buf,
 11200                               uint32 error_buf_size)
 11201  {
 11202      uint8 *p = func->code, *p_end = func->code + func->code_size, *p_org;
 11203      uint32 param_count, local_count, global_count;
 11204      uint8 *param_types, *local_types, local_type, global_type, mem_offset_type,
 11205          table_elem_idx_type;
 11206      BlockType func_block_type;
 11207      uint16 *local_offsets, local_offset;
 11208      uint32 type_idx, func_idx, local_idx, global_idx, table_idx;
 11209      uint32 table_seg_idx, data_seg_idx, count, align, i;
 11210      mem_offset_t mem_offset;
 11211      int32 i32_const = 0;
 11212      int64 i64_const;
 11213      uint8 opcode;
 11214      bool return_value = false;
 11215      WASMLoaderContext *loader_ctx;
 11216      BranchBlock *frame_csp_tmp;
 11217  #if WASM_ENABLE_GC != 0
 11218      WASMRefTypeMap *param_reftype_maps, *local_reftype_maps;
 11219      uint32 param_reftype_map_count, local_reftype_map_count;
 11220      int32 heap_type;
 11221      WASMRefType wasm_ref_type = { 0 };
 11222      bool need_ref_type_map;
 11223  #endif
 11224  #if WASM_ENABLE_FAST_INTERP != 0
 11225      int16 operand_offset = 0;
 11226      uint8 last_op = 0;
 11227      bool disable_emit, preserve_local = false, if_condition_available = true;
 11228      float32 f32_const;
 11229      float64 f64_const;
 11230
 11231      LOG_OP("\nProcessing func | [%d] params | [%d] locals | [%d] return\n",
 11232             func->param_cell_num, func->local_cell_num, func->ret_cell_num);
 11233  #endif
 11234  #if WASM_ENABLE_MEMORY64 != 0
 11235      bool is_memory64 = has_module_memory64(module);
 11236      mem_offset_type = is_memory64 ? VALUE_TYPE_I64 : VALUE_TYPE_I32;
 11237  #else
 11238      mem_offset_type = VALUE_TYPE_I32;
 11239      table_elem_idx_type = VALUE_TYPE_I32;
 11240  #endif
 11241      uint32 memidx;
 11242
 11243      global_count = module->import_global_count + module->global_count;
 11244
 11245      param_count = func->func_type->param_count;
 11246      param_types = func->func_type->types;
 11247
 11248      func_block_type.is_value_type = false;
 11249      func_block_type.u.type = func->func_type;
 11250
 11251      local_count = func->local_count;
 11252      local_types = func->local_types;
 11253      local_offsets = func->local_offsets;
 11254
 11255  #if WASM_ENABLE_GC != 0
 11256      param_reftype_maps = func->func_type->ref_type_maps;
 11257      param_reftype_map_count = func->func_type->ref_type_map_count;
 11258      local_reftype_maps = func->local_ref_type_maps;
 11259      local_reftype_map_count = func->local_ref_type_map_count;
 11260  #endif
 11261
 11262      if (!(loader_ctx = wasm_loader_ctx_init(func, error_buf, error_buf_size))) {
 11263          goto fail;
 11264      }
 11265  #if WASM_ENABLE_GC != 0
 11266      loader_ctx->module = module;
 11267      loader_ctx->ref_type_set = module->ref_type_set;
 11268      loader_ctx->ref_type_tmp = &wasm_ref_type;
 11269  #endif
 11270
 11271  #if WASM_ENABLE_FAST_INTERP != 0
 11272      /* For the first traverse, the initial value of preserved_local_offset has
 11273       * not been determined, we use the INT16_MAX to represent that a slot has
 11274       * been copied to preserve space. For second traverse, this field will be
 11275       * set to the appropriate value in wasm_loader_ctx_reinit.
 11276       * This is for Issue #1230,
 11277       * https://github.com/bytecodealliance/wasm-micro-runtime/issues/1230, the
 11278       * drop opcodes need to know which slots are preserved, so those slots will
 11279       * not be treated as dynamically allocated slots */
 11280      loader_ctx->preserved_local_offset = INT16_MAX;
 11281
 11282  re_scan:
 11283      if (loader_ctx->code_compiled_size > 0) {
 11284          if (!wasm_loader_ctx_reinit(loader_ctx)) {
 11285              set_error_buf(error_buf, error_buf_size, "allocate memory failed");
 11286              goto fail;
 11287          }
 11288          p = func->code;
 11289          func->code_compiled = loader_ctx->p_code_compiled;
 11290          func->code_compiled_size = loader_ctx->code_compiled_size;
 11291
 11292          if (loader_ctx->i64_const_num > 0) {
 11293              int64 *i64_consts_old = loader_ctx->i64_consts;
 11294
 11295              /* Sort the i64 consts */
 11296              qsort(i64_consts_old, loader_ctx->i64_const_num, sizeof(int64),
 11297                    cmp_i64_const);
 11298
 11299              /* Remove the duplicated i64 consts */
 11300              uint32 k = 1;
 11301              for (i = 1; i < loader_ctx->i64_const_num; i++) {
 11302                  if (i64_consts_old[i] != i64_consts_old[i - 1]) {
 11303                      i64_consts_old[k++] = i64_consts_old[i];
 11304                  }
 11305              }
 11306
 11307              if (k < loader_ctx->i64_const_num) {
 11308                  int64 *i64_consts_new;
 11309                  /* Try to reallocate memory with a smaller size */
 11310                  if ((i64_consts_new =
 11311                           wasm_runtime_malloc((uint32)sizeof(int64) * k))) {
 11312                      bh_memcpy_s(i64_consts_new, (uint32)sizeof(int64) * k,
 11313                                  i64_consts_old, (uint32)sizeof(int64) * k);
 11314                      /* Free the old memory */
 11315                      wasm_runtime_free(i64_consts_old);
 11316                      loader_ctx->i64_consts = i64_consts_new;
 11317                      loader_ctx->i64_const_max_num = k;
 11318                  }
 11319                  loader_ctx->i64_const_num = k;
 11320              }
 11321          }
 11322
 11323          if (loader_ctx->v128_const_num > 0) {
 11324              V128 *v128_consts_old = loader_ctx->v128_consts;
 11325
 11326              /* Sort the v128 consts */
 11327              qsort(v128_consts_old, loader_ctx->v128_const_num, sizeof(V128),
 11328                    cmp_v128_const);
 11329
 11330              /* Remove the duplicated v128 consts */
 11331              uint32 k = 1;
 11332              for (i = 1; i < loader_ctx->v128_const_num; i++) {
 11333                  if (!(memcmp(&v128_consts_old[i], &v128_consts_old[i - 1],
 11334                               sizeof(V128))
 11335                        == 0)) {
 11336                      v128_consts_old[k++] = v128_consts_old[i];
 11337                  }
 11338              }
 11339
 11340              if (k < loader_ctx->v128_const_num) {
 11341                  V128 *v128_consts_new;
 11342                  /* Try to reallocate memory with a smaller size */
 11343                  if ((v128_consts_new =
 11344                           wasm_runtime_malloc((uint32)sizeof(V128) * k))) {
 11345                      bh_memcpy_s(v128_consts_new, (uint32)sizeof(V128) * k,
 11346                                  v128_consts_old, (uint32)sizeof(V128) * k);
 11347                      /* Free the old memory */
 11348                      wasm_runtime_free(v128_consts_old);
 11349                      loader_ctx->v128_consts = v128_consts_new;
 11350                      loader_ctx->v128_const_max_num = k;
 11351                  }
 11352                  loader_ctx->v128_const_num = k;
 11353              }
 11354          }
 11355
 11356          if (loader_ctx->i32_const_num > 0) {
 11357              int32 *i32_consts_old = loader_ctx->i32_consts;
 11358
 11359              /* Sort the i32 consts */
 11360              qsort(i32_consts_old, loader_ctx->i32_const_num, sizeof(int32),
 11361                    cmp_i32_const);
 11362
 11363              /* Remove the duplicated i32 consts */
 11364              uint32 k = 1;
 11365              for (i = 1; i < loader_ctx->i32_const_num; i++) {
 11366                  if (i32_consts_old[i] != i32_consts_old[i - 1]) {
 11367                      i32_consts_old[k++] = i32_consts_old[i];
 11368                  }
 11369              }
 11370
 11371              if (k < loader_ctx->i32_const_num) {
 11372                  int32 *i32_consts_new;
 11373                  /* Try to reallocate memory with a smaller size */
 11374                  if ((i32_consts_new =
 11375                           wasm_runtime_malloc((uint32)sizeof(int32) * k))) {
 11376                      bh_memcpy_s(i32_consts_new, (uint32)sizeof(int32) * k,
 11377                                  i32_consts_old, (uint32)sizeof(int32) * k);
 11378                      /* Free the old memory */
 11379                      wasm_runtime_free(i32_consts_old);
 11380                      loader_ctx->i32_consts = i32_consts_new;
 11381                      loader_ctx->i32_const_max_num = k;
 11382                  }
 11383                  loader_ctx->i32_const_num = k;
 11384              }
 11385          }
 11386      }
 11387  #endif
 11388
 11389      PUSH_CSP(LABEL_TYPE_FUNCTION, func_block_type, p);
 11390
 11391      while (p < p_end) {
 11392          opcode = *p++;
 11393  #if WASM_ENABLE_FAST_INTERP != 0
 11394          p_org = p;
 11395          disable_emit = false;
 11396          emit_label(opcode);
 11397  #endif
 11398          switch (opcode) {
 11399              case WASM_OP_UNREACHABLE:
 11400                  RESET_STACK();
 11401                  SET_CUR_BLOCK_STACK_POLYMORPHIC_STATE(true);
 11402                  break;
 11403
 11404              case WASM_OP_NOP:
 11405  #if WASM_ENABLE_FAST_INTERP != 0
 11406                  skip_label();
 11407  #endif
 11408                  break;
 11409
 11410              case WASM_OP_IF:
 11411              {
 11412  #if WASM_ENABLE_FAST_INTERP != 0
 11413                  BranchBlock *parent_block = loader_ctx->frame_csp - 1;
 11414                  int32 available_stack_cell =
 11415                      (int32)(loader_ctx->stack_cell_num
 11416                              - parent_block->stack_cell_num);
 11417
 11418                  if (available_stack_cell <= 0
 11419                      && parent_block->is_stack_polymorphic)
 11420                      if_condition_available = false;
 11421                  else
 11422                      if_condition_available = true;
 11423
 11424                  PRESERVE_LOCAL_FOR_BLOCK();
 11425  #endif
 11426  #if WASM_ENABLE_GC == 0
 11427                  POP_I32();
 11428  #endif
 11429                  goto handle_op_block_and_loop;
 11430              }
 11431              case WASM_OP_BLOCK:
 11432              case WASM_OP_LOOP:
 11433  #if WASM_ENABLE_EXCE_HANDLING != 0
 11434              case WASM_OP_TRY:
 11435                  if (opcode == WASM_OP_TRY) {
 11436                      /*
 11437                       * keep track of exception handlers to account for
 11438                       * memory allocation
 11439                       */
 11440                      func->exception_handler_count++;
 11441
 11442                      /*
 11443                       * try is a block
 11444                       * do nothing special, but execution continues to
 11445                       * to handle_op_block_and_loop,
 11446                       * and that be pushes the csp
 11447                       */
 11448                  }
 11449
 11450  #endif
 11451  #if WASM_ENABLE_FAST_INTERP != 0
 11452                  PRESERVE_LOCAL_FOR_BLOCK();
 11453  #endif
 11454              handle_op_block_and_loop:
 11455              {
 11456                  uint8 value_type;
 11457                  BlockType block_type;
 11458  #if WASM_ENABLE_FAST_INTERP != 0
 11459                  uint32 available_params = 0;
 11460  #endif
 11461
 11462                  CHECK_BUF(p, p_end, 1);
 11463                  value_type = read_uint8(p);
 11464                  if (is_byte_a_type(value_type)) {
 11465                      /* If the first byte is one of these special values:
 11466                       * 0x40/0x7F/0x7E/0x7D/0x7C, take it as the type of
 11467                       * the single return value. */
 11468                      block_type.is_value_type = true;
 11469                      block_type.u.value_type.type = value_type;
 11470  #if WASM_ENABLE_WAMR_COMPILER != 0
 11471                      if (value_type == VALUE_TYPE_V128)
 11472                          module->is_simd_used = true;
 11473                      else if (value_type == VALUE_TYPE_FUNCREF
 11474                               || value_type == VALUE_TYPE_EXTERNREF)
 11475                          module->is_ref_types_used = true;
 11476  #endif
 11477  #if WASM_ENABLE_GC != 0
 11478                      if (value_type != VALUE_TYPE_VOID) {
 11479                          p_org = p;
 11480                          p--;
 11481                          if (!resolve_value_type((const uint8 **)&p, p_end,
 11482                                                  module, module->type_count,
 11483                                                  &need_ref_type_map,
 11484                                                  &wasm_ref_type, false,
 11485                                                  error_buf, error_buf_size)) {
 11486                              goto fail;
 11487                          }
 11488                          if (need_ref_type_map) {
 11489                              block_type.u.value_type.ref_type_map.index = 0;
 11490                              if (!(block_type.u.value_type.ref_type_map
 11491                                        .ref_type = reftype_set_insert(
 11492                                        module->ref_type_set, &wasm_ref_type,
 11493                                        error_buf, error_buf_size))) {
 11494                                  goto fail;
 11495                              }
 11496                          }
 11497                          /* Set again as the type might be changed, e.g.
 11498                             (ref null any) to anyref */
 11499                          block_type.u.value_type.type = wasm_ref_type.ref_type;
 11500  #if WASM_ENABLE_FAST_INTERP == 0
 11501                          while (p_org < p) {
 11502  #if WASM_ENABLE_DEBUG_INTERP != 0
 11503                              if (!record_fast_op(module, p_org, *p_org,
 11504                                                  error_buf, error_buf_size)) {
 11505                                  goto fail;
 11506                              }
 11507  #endif
 11508                              /* Ignore extra bytes for interpreter */
 11509                              *p_org++ = WASM_OP_NOP;
 11510                          }
 11511  #endif
 11512                      }
 11513  #endif /* end of WASM_ENABLE_GC != 0 */
 11514                  }
 11515                  else {
 11516                      int32 type_index;
 11517                      /* Resolve the leb128 encoded type index as block type */
 11518                      p--;
 11519                      p_org = p - 1;
 11520                      pb_read_leb_int32(p, p_end, type_index);
 11521                      if ((uint32)type_index >= module->type_count) {
 11522                          set_error_buf(error_buf, error_buf_size,
 11523                                        "unknown type");
 11524                          goto fail;
 11525                      }
 11526                      block_type.is_value_type = false;
 11527                      block_type.u.type =
 11528                          (WASMFuncType *)module->types[type_index];
 11529  #if WASM_ENABLE_FAST_INTERP == 0
 11530                      /* If block use type index as block type, change the opcode
 11531                       * to new extended opcode so that interpreter can resolve
 11532                       * the block quickly.
 11533                       */
 11534  #if WASM_ENABLE_DEBUG_INTERP != 0
 11535                      if (!record_fast_op(module, p_org, *p_org, error_buf,
 11536                                          error_buf_size)) {
 11537                          goto fail;
 11538                      }
 11539  #endif
 11540                      *p_org = EXT_OP_BLOCK + (opcode - WASM_OP_BLOCK);
 11541  #endif
 11542                  }
 11543
 11544  #if WASM_ENABLE_GC != 0
 11545                  if (opcode == WASM_OP_IF) {
 11546                      POP_I32();
 11547                  }
 11548  #endif
 11549
 11550                  /* Pop block parameters from stack */
 11551                  if (BLOCK_HAS_PARAM(block_type)) {
 11552                      WASMFuncType *wasm_type = block_type.u.type;
 11553
 11554                      BranchBlock *cur_block = loader_ctx->frame_csp - 1;
 11555  #if WASM_ENABLE_FAST_INTERP != 0
 11556                      uint32 cell_num;
 11557                      available_params = block_type.u.type->param_count;
 11558  #endif
 11559                      for (i = 0; i < block_type.u.type->param_count; i++) {
 11560
 11561                          int32 available_stack_cell =
 11562                              (int32)(loader_ctx->stack_cell_num
 11563                                      - cur_block->stack_cell_num);
 11564                          if (available_stack_cell <= 0
 11565                              && cur_block->is_stack_polymorphic) {
 11566  #if WASM_ENABLE_FAST_INTERP != 0
 11567                              available_params = i;
 11568  #endif
 11569                              break;
 11570                          }
 11571
 11572                          POP_TYPE(
 11573                              wasm_type->types[wasm_type->param_count - i - 1]);
 11574  #if WASM_ENABLE_FAST_INTERP != 0
 11575                          /* decrease the frame_offset pointer accordingly to keep
 11576                           * consistent with frame_ref stack */
 11577                          cell_num = wasm_value_type_cell_num(
 11578                              wasm_type->types[wasm_type->param_count - i - 1]);
 11579                          loader_ctx->frame_offset -= cell_num;
 11580  #endif
 11581                      }
 11582                  }
 11583                  PUSH_CSP(LABEL_TYPE_BLOCK + (opcode - WASM_OP_BLOCK),
 11584                           block_type, p);
 11585
 11586                  /* Pass parameters to block */
 11587                  if (BLOCK_HAS_PARAM(block_type)) {
 11588                      WASMFuncType *func_type = block_type.u.type;
 11589  #if WASM_ENABLE_GC != 0
 11590                      WASMRefType *ref_type;
 11591                      uint32 j = 0;
 11592  #endif
 11593                      for (i = 0; i < func_type->param_count; i++) {
 11594  #if WASM_ENABLE_FAST_INTERP != 0
 11595                          uint32 cell_num =
 11596                              wasm_value_type_cell_num(func_type->types[i]);
 11597                          if (i >= available_params) {
 11598                              /* make sure enough space */
 11599                              if (loader_ctx->p_code_compiled == NULL) {
 11600                                  loader_ctx->frame_offset += cell_num;
 11601                                  if (!check_offset_push(loader_ctx, error_buf,
 11602                                                         error_buf_size))
 11603                                      goto fail;
 11604                                  /* for following dummy value assignment */
 11605                                  loader_ctx->frame_offset -= cell_num;
 11606                              }
 11607
 11608                              /* If there isn't enough data on stack, push a dummy
 11609                               * offset to keep the stack consistent with
 11610                               * frame_ref.
 11611                               * Since the stack is already in polymorphic state,
 11612                               * the opcode will not be executed, so the dummy
 11613                               * offset won't cause any error */
 11614                              for (uint32 n = 0; n < cell_num; n++) {
 11615                                  *loader_ctx->frame_offset++ = 0;
 11616                              }
 11617                          }
 11618                          else {
 11619                              loader_ctx->frame_offset += cell_num;
 11620                          }
 11621  #endif
 11622  #if WASM_ENABLE_GC != 0
 11623                          if (wasm_is_type_multi_byte_type(func_type->types[i])) {
 11624                              bh_assert(func_type->ref_type_maps[j].index == i);
 11625                              ref_type = func_type->ref_type_maps[j].ref_type;
 11626                              bh_memcpy_s(&wasm_ref_type, sizeof(WASMRefType),
 11627                                          ref_type,
 11628                                          wasm_reftype_struct_size(ref_type));
 11629                              j++;
 11630                          }
 11631  #endif
 11632                          PUSH_TYPE(func_type->types[i]);
 11633                      }
 11634                  }
 11635
 11636  #if WASM_ENABLE_FAST_INTERP != 0
 11637                  if (opcode == WASM_OP_BLOCK || opcode == WASM_OP_LOOP) {
 11638                      skip_label();
 11639
 11640                      if (BLOCK_HAS_PARAM(block_type)) {
 11641                          /* Make sure params are in dynamic space */
 11642                          if (!copy_params_to_dynamic_space(loader_ctx, error_buf,
 11643                                                            error_buf_size))
 11644                              goto fail;
 11645                      }
 11646
 11647                      if (opcode == WASM_OP_LOOP) {
 11648                          (loader_ctx->frame_csp - 1)->code_compiled =
 11649                              loader_ctx->p_code_compiled;
 11650                      }
 11651                  }
 11652  #if WASM_ENABLE_EXCE_HANDLING != 0
 11653                  else if (opcode == WASM_OP_TRY) {
 11654                      skip_label();
 11655                  }
 11656  #endif
 11657                  else if (opcode == WASM_OP_IF) {
 11658                      BranchBlock *block = loader_ctx->frame_csp - 1;
 11659                      /* If block has parameters, we should make sure they are in
 11660                       * dynamic space. Otherwise, when else branch is missing,
 11661                       * the later opcode may consume incorrect operand offset.
 11662                       * Spec case:
 11663                       *   (func (export "params-id") (param i32) (result i32)
 11664                       *       (i32.const 1)
 11665                       *       (i32.const 2)
 11666                       *       (if (param i32 i32) (result i32 i32) (local.get 0)
 11667                       *       (then)) (i32.add)
 11668                       *   )
 11669                       *
 11670                       * So we should emit a copy instruction before the if.
 11671                       *
 11672                       * And we also need to save the parameter offsets and
 11673                       * recover them before entering else branch.
 11674                       *
 11675                       */
 11676                      if (BLOCK_HAS_PARAM(block_type)) {
 11677                          uint64 size;
 11678
 11679                          /* In polymorphic state, there may be no if condition on
 11680                           * the stack, so the offset may not emitted */
 11681                          if (if_condition_available) {
 11682                              /* skip the if condition operand offset */
 11683                              wasm_loader_emit_backspace(loader_ctx,
 11684                                                         sizeof(int16));
 11685                          }
 11686                          /* skip the if label */
 11687                          skip_label();
 11688                          /* Emit a copy instruction */
 11689                          if (!copy_params_to_dynamic_space(loader_ctx, error_buf,
 11690                                                            error_buf_size))
 11691                              goto fail;
 11692
 11693                          /* Emit the if instruction */
 11694                          emit_label(opcode);
 11695                          /* Emit the new condition operand offset */
 11696                          POP_OFFSET_TYPE(VALUE_TYPE_I32);
 11697
 11698                          /* Save top param_count values of frame_offset stack, so
 11699                           * that we can recover it before executing else branch
 11700                           */
 11701                          size = sizeof(int16)
 11702                                 * (uint64)block_type.u.type->param_cell_num;
 11703                          if (!(block->param_frame_offsets = loader_malloc(
 11704                                    size, error_buf, error_buf_size)))
 11705                              goto fail;
 11706                          bh_memcpy_s(block->param_frame_offsets, (uint32)size,
 11707                                      loader_ctx->frame_offset
 11708                                          - size / sizeof(int16),
 11709                                      (uint32)size);
 11710                      }
 11711
 11712                      block->start_dynamic_offset = loader_ctx->dynamic_offset;
 11713
 11714                      emit_empty_label_addr_and_frame_ip(PATCH_ELSE);
 11715                      emit_empty_label_addr_and_frame_ip(PATCH_END);
 11716                  }
 11717  #endif
 11718                  break;
 11719              }
 11720  #if WASM_ENABLE_EXCE_HANDLING != 0
 11721              case WASM_OP_THROW:
 11722              {
 11723                  SET_CUR_BLOCK_STACK_POLYMORPHIC_STATE(true);
 11724
 11725                  BranchBlock *cur_block = loader_ctx->frame_csp - 1;
 11726
 11727                  uint8 label_type = cur_block->label_type;
 11728                  uint32 tag_index = 0;
 11729                  pb_read_leb_int32(p, p_end, tag_index);
 11730
 11731                  /* check validity of tag_index against module->tag_count */
 11732                  /* check tag index is within the tag index space */
 11733                  if (tag_index >= module->import_tag_count + module->tag_count) {
 11734                      snprintf(error_buf, error_buf_size, "unknown tag %d",
 11735                               tag_index);
 11736                      goto fail;
 11737                  }
 11738
 11739                  /* the tag_type is stored in either the WASMTag (section tags)
 11740                   * or WASMTagImport (import tag) */
 11741                  WASMFuncType *tag_type = NULL;
 11742                  if (tag_index < module->import_tag_count) {
 11743                      tag_type = module->import_tags[tag_index].u.tag.tag_type;
 11744                  }
 11745                  else {
 11746                      tag_type =
 11747                          module->tags[tag_index - module->import_tag_count]
 11748                              ->tag_type;
 11749                  }
 11750
 11751                  if (tag_type->result_count != 0) {
 11752                      set_error_buf(error_buf, error_buf_size,
 11753                                    "tag type signature does not return void");
 11754                      goto fail;
 11755                  }
 11756
